function parseRichText(html: string): Node[] {
  const nodes: Node[] = [];
  let i = 0;

  while (i < html.length) {
    const tagMatch = html.slice(i).match(/^<(\/)?(\w+)(?:\s+href="([^"]*)")?">/);

    if (tagMatch) {
      const [fullTag, isClosing, tagName, hrefValue] = tagMatch;
      const tagLength = fullTag.length;

      if (isClosing) {
        nodes.push(html.slice(i, i + tagLength));
        i += tagLength;
      } else if (tagName === 'br') {
        nodes.push(html.slice(i, i + tagLength));
        i += tagLength;
      } else if (tagName === 'b' || tagName === 'strong' || tagName === 'i' || tagName === 'em' || tagName === 'a') {
        nodes.push(html.slice(i, i + tagLength));
        i += tagLength;
      } else {
        const char = html[i];
        if (nodes.length && typeof nodes[nodes.length - 1] === 'string') {
          nodes[nodes.length - 1] += char;
        } else {
          nodes.push(char);
        }
        i++;
      }
    } else {
      const char = html[i];
      if (nodes.length && typeof nodes[nodes.length - 1] === 'string') {
        nodes[nodes.length - 1] += char;
      } else {
        nodes.push(char);
      }
      i++;
    }
  }

  return nodes;
}

function buildRichTextDOM(html: string): DocumentFragment {
  const fragment = document.createDocumentFragment();
  const stack: Element[] = [];
  let currentText = '';

  const pushText = () => {
    if (currentText) {
      fragment.appendChild(document.createTextNode(currentText));
      currentText = '';
    }
  };

  let i = 0;
  while (i < html.length) {
    const remaining = html.slice(i);

    const brMatch = remaining.match(/^<br\s*\/?>|<br>/);
    if (brMatch) {
      pushText();
      fragment.appendChild(document.createElement('br'));
      i += brMatch[0].length;
      continue;
    }

    const tagMatch = remaining.match(/^<(\/)?([a-z]+)(?:\s+href="([^"]*)")?>"/);
    if (tagMatch) {
      const [fullTag, isClosing, tagName, href] = tagMatch;

      if (isClosing) {
        pushText();
        if (stack.length && stack[stack.length - 1].tagName.toLowerCase() === tagName) {
          const element = stack.pop()!;
          fragment.appendChild(element);
        }
        i += fullTag.length;
      } else if (['b', 'strong', 'i', 'em', 'a'].includes(tagName)) {
        pushText();
        const element = document.createElement(tagName === 'strong' ? 'b' : tagName === 'em' ? 'i' : tagName);
        if (tagName === 'a' && href) {
          element.setAttribute('href', href);
        }
        stack.push(element);
        i += fullTag.length;
      } else {
        currentText += html[i];
        i++;
      }
    } else {
      currentText += html[i];
      i++;
    }
  }

  pushText();

  while (stack.length) {
    fragment.appendChild(stack.pop()!);
  }

  return fragment;
}

