    return /^(https?|data):/.test(parsed.protocol);
  } catch {
    return false;
  }
}

function addNote(title: string, body: string, avatar: string): void {
  if (!title.trim() || !body.trim()) return;
  if (avatar && !validateAvatarUrl(avatar)) return;

  const newNote: Note = {
    id: ++maxNoteId,
    title: title.trim(),
    body: body.trim(),
    avatar: avatar.trim(),
    createdAt: new Date().toISOString(),
  };

  notes.unshift(newNote);
  saveNotes();
  renderFeed();
  form.reset();
}

function buildRichTextDOM(html: string): DocumentFragment {
  const fragment = document.createDocumentFragment();
  const stack: Element[] = [];
  let currentText = '';

  const flushText = () => {
    if (currentText) {
      const textNode = document.createTextNode(currentText);
      if (stack.length > 0) {
        stack[stack.length - 1]?.appendChild(textNode);
      } else {
        fragment.appendChild(textNode);
      }
      currentText = '';
    }
  };

  let i = 0;
  while (i < html.length) {
    const remaining = html.slice(i);

    const brMatch = remaining.match(/^<br\s*\/?>/);
    if (brMatch) {
      flushText();
      const br = document.createElement('br');
      if (stack.length > 0) {
        stack[stack.length - 1]?.appendChild(br);
      } else {
        fragment.appendChild(br);
      }
      i += brMatch[0].length;
      continue;
    }

    const closeMatch = remaining.match(/^<\/(b|strong|i|em|a)>/);
    if (closeMatch) {
      flushText();
      const element = stack.pop();
      if (element) {
        if (stack.length > 0) {
          stack[stack.length - 1]?.appendChild(element);
        } else {
          fragment.appendChild(element);
        }
      }
      i += closeMatch[0].length;
      continue;
    }

    const openMatch = remaining.match(/^<(b|strong|i|em)>/);
    if (openMatch && openMatch[1]) {
      flushText();
      const tagName = openMatch[1] === 'strong' ? 'b' : openMatch[1] === 'em' ? 'i' : openMatch[1];
      const element = document.createElement(tagName);
      stack.push(element);
      i += openMatch[0].length;
      continue;
    }

    const linkMatch = remaining.match(/^<a\s+href="([^"]*)">/);
    if (linkMatch && linkMatch[1]) {
      flushText();
      const element = document.createElement('a');
      element.setAttribute('href', linkMatch[1]);
      stack.push(element);
      i += linkMatch[0].length;
      continue;
    }

    currentText += html[i];
    i++;
  }

  flushText();

  while (stack.length > 0) {
    const element = stack.pop();
    if (element) {
      if (stack.length > 0) {
        stack[stack.length - 1]?.appendChild(element);
      } else {
        fragment.appendChild(element);
      }
    }
  }

